using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.Linq;
public static class FinishTrike {public static string Main(){const string dir="Assets/Models/3WheelCar/Driveable/";var root=PrefabUtility.LoadPrefabContents(dir+"Trike_Driveable.prefab");try{foreach(var r in root.GetComponentsInChildren<Renderer>()){var mats=r.sharedMaterials;for(int i=0;i<mats.Length;i++){var path=dir+mats[i].name+" Interior.mat";var mat=AssetDatabase.LoadAssetAtPath<Material>(path);if(mat==null){mat=new Material(mats[i]);mat.name=mats[i].name+" Interior";mat.SetFloat("_DoubleSidedEnable",1);mat.SetFloat("_DoubleSidedNormalMode",0);UnityEditor.Rendering.HighDefinition.HDShaderUtils.ResetMaterialKeywords(mat);AssetDatabase.CreateAsset(mat,path);}mats[i]=mat;}r.sharedMaterials=mats;}PrefabUtility.SaveAsPrefabAsset(root,dir+"Trike_Driveable.prefab");AssetDatabase.SaveAssets();}finally{PrefabUtility.UnloadPrefabContents(root);}var trike=Object.FindFirstObjectByType<TrikeController>();EditorSceneManager.MarkSceneDirty(trike.gameObject.scene);EditorSceneManager.SaveScene(trike.gameObject.scene);Physics.SyncTransforms();return "Saved interior materials; nearby obstacles="+string.Join(", ",Physics.OverlapBox(trike.transform.TransformPoint(new Vector3(0,1.13f,0)),Vector3.Scale(new Vector3(.94f,.94f,1.91f),trike.transform.lossyScale),trike.transform.rotation).Where(c=>!c.transform.IsChildOf(trike.transform)).Select(c=>c.name));}}
